// swift-tools-version:6.2
import PackageDescription

// Standalone macOS qualification for the T4 Office/media automation lane:
// the authorized automatic copy executor, the formula cached-result verifier
// and the action-aware native job policy, exercised against real OOXML
// fixture files (Fixtures/, generated by make_fixtures.py). The app-only
// engine session is faked here; the device engine path is qualified by the
// primary's full-App build.
//
// Build/run (isolated scratch on the internal SSD):
//   DEVELOPER_DIR=/Applications/Xcode.app/Contents/Developer \
//   swift run --package-path FloeAgent/Qualification/OfficeAutomation \
//     --scratch-path ~/Library/Caches/CodexBuild/Floe/capability-closure-20261014/automation/officequal \
//     --jobs 3 FloeOfficeAutomationQualification <work-dir>
let package = Package(
    name: "FloeOfficeAutomationQualification",
    platforms: [.macOS(.v15)],
    dependencies: [
        .package(path: "../..")
    ],
    targets: [
        .executableTarget(
            name: "FloeOfficeAutomationQualification",
            dependencies: [
                .product(name: "FloeCore", package: "FloeAgent"),
                .product(name: "FloeTools", package: "FloeAgent"),
                .product(name: "FloeDocuments", package: "FloeAgent"),
                .product(name: "FloePersistence", package: "FloeAgent"),
                .product(name: "FloeExecution", package: "FloeAgent"),
                .product(name: "FloeMedia", package: "FloeAgent")
            ],
            path: "Sources"
        )
    ]
)
